"use client";

import * as React from "react";
import { ArrowDownToLine, ChevronLeft } from "lucide-react";
import { Faces, FACES_MORPH } from "./faces";
import { NumberRoll } from "./number-roll";
import { SegmentedControl } from "./segmented-control";
import { StatusButton, type ActionStatus } from "./status-button";
import { Textarea } from "./textarea";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SUBSCRIPTION: a plan you can see through to its next bill
 *
 *   plan      the lit card holds the plan, its price and a ring
 *             that fills through the billing period, the days left
 *             in its middle; under it usage, the card on file and
 *             invoices, all flat
 *   pause     Cancel plan turns the lower half into "Pause
 *             instead?": pick one, two or three months and the date
 *             billing resumes rolls to match
 *   cancel    only past the offer, a reason and a note, then
 *             Cancel subscription; the card says when it ends
 *   resume    a paused or ending plan offers Resume in place
 *
 * Billing is yours: pass the plan, status, period and usage from
 * your provider, and do the work in onPause, onCancel, onResume and
 * onUpdateCard (open your provider's portal there). Throw an Error
 * and its message shows where it happened.
 * ───────────────────────────────────────────────────────── */

export type SubscriptionStatus =
  "active" | "trialing" | "past_due" | "paused" | "canceling";

export interface SubscriptionPlan {
  name: string;
  /** Per interval, major units. */
  price: number;
  interval: "month" | "year";
  seats?: number;
}

export interface SubscriptionUsage {
  id: string;
  label: string;
  used: number;
  limit: number;
  /** e.g. "runs", "GB". */
  unit?: string;
}

export interface SubscriptionCard {
  /** e.g. "Visa". */
  brand: string;
  last4: string;
  expMonth: number;
  expYear: number;
}

export interface SubscriptionInvoice {
  id: string;
  date: Date | string | number;
  amount: number;
  status: "paid" | "open" | "failed";
  /** A PDF or hosted invoice page. */
  url?: string;
}

export interface SubscriptionProps {
  plan: SubscriptionPlan;
  status: SubscriptionStatus;
  periodStart: Date | string | number;
  /** When it renews, or ends while canceling. */
  periodEnd: Date | string | number;
  /** When billing resumes, while paused. */
  resumesAt?: Date | string | number;
  usage?: SubscriptionUsage[];
  card?: SubscriptionCard;
  invoices?: SubscriptionInvoice[];
  /** Open your provider's portal (or a form) to change the card. */
  onUpdateCard?: () => Promise<unknown>;
  /** Go to your plans, e.g. the Pricing plans block. */
  onChangePlan?: () => void;
  /** Pause billing for this many months; shows the offer before cancelling. */
  onPause?: (months: number) => Promise<unknown>;
  onCancel?: (reason: string, comment: string) => Promise<unknown>;
  /** Undo a pause or a cancel that hasn't ended yet. */
  onResume?: () => Promise<unknown>;
  pauseMonths?: number[];
  reasons?: string[];
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DAY = 86_400_000;
const PAUSE = [1, 2, 3];
const REASONS = [
  "Too expensive",
  "Not using it enough",
  "Missing a feature",
  "Switching to another tool",
  "Something else",
];
const NONE: never[] = [];
const subscribeNothing = () => () => {};
/** False on the server and while hydrating, so dates are written once, in the visitor's own zone. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const LIT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 100% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const ACTION: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const errorOf = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const addMonths = (t: number, m: number) => {
  const d = new Date(t);
  d.setMonth(d.getMonth() + m);
  return d.getTime();
};

/** The billing period as a ring: how far through it you are, the days left in the middle. */
function PeriodRing({
  share,
  days,
  dim,
  reduced,
}: {
  share: number;
  days: number | null;
  dim: boolean;
  reduced: boolean;
}) {
  const r = 22;
  const c = 2 * Math.PI * r;
  return (
    <span
      className="relative flex size-[56px] shrink-0 items-center justify-center"
      style={{ opacity: dim ? 0.55 : 1, transition: "opacity 400ms" }}
    >
      <svg
        aria-hidden="true"
        viewBox="0 0 56 56"
        className="absolute inset-0 size-full -rotate-90"
      >
        <circle
          cx="28"
          cy="28"
          r={r}
          fill="none"
          stroke={mix("var(--primary-foreground)", 22)}
          strokeWidth="3"
        />
        <circle
          cx="28"
          cy="28"
          r={r}
          fill="none"
          stroke="var(--primary-foreground)"
          strokeWidth="3"
          strokeLinecap="round"
          strokeDasharray={c}
          style={{
            strokeDashoffset: c * (1 - share),
            transition: reduced ? "none" : `stroke-dashoffset 900ms ${EASE}`,
          }}
        />
        {/* Fine ticks round the ring, one per week of the period. */}
        {Array.from({ length: 12 }, (_, i) => (
          <line
            key={i}
            x1="28"
            y1="1.5"
            x2="28"
            y2="3.5"
            stroke={mix("var(--primary-foreground)", 35)}
            strokeWidth="0.8"
            transform={`rotate(${i * 30} 28 28)`}
          />
        ))}
      </svg>
      <span className="relative text-center leading-none">
        <span className="block text-[16px] font-medium tabular-nums">
          {days === null ? "–" : <NumberRoll value={days} duration={800} />}
        </span>
        <span className="mt-0.5 block text-[9.5px] uppercase tracking-[0.08em] text-primary-foreground/70">
          {days === 1 ? "day" : "days"}
        </span>
      </span>
    </span>
  );
}

export function Subscription({
  plan,
  status,
  periodStart,
  periodEnd,
  resumesAt,
  usage = NONE,
  card,
  invoices = NONE,
  onUpdateCard,
  onChangePlan,
  onPause,
  onCancel,
  onResume,
  pauseMonths = PAUSE,
  reasons = REASONS,
  currency = "USD",
  locale,
  className = "",
}: SubscriptionProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const loc = locale ?? (hydrated ? undefined : "en-US");
  const [now, setNow] = React.useState<number | null>(null);
  const [ready, setReady] = React.useState(false);
  const [step, setStep] = React.useState<0 | 1 | 2>(0);
  const [months, setMonths] = React.useState(
    pauseMonths[Math.min(1, pauseMonths.length - 1)] ?? 1,
  );
  const [reason, setReason] = React.useState<string | null>(null);
  const [comment, setComment] = React.useState("");
  const [act, setAct] = React.useState<{
    kind: "pause" | "cancel" | "resume" | "card" | null;
    status: ActionStatus;
    error?: string;
  }>({ kind: null, status: "idle" });
  const [said, setSaid] = React.useState("");
  const faceRefs = React.useRef<(HTMLElement | null)[]>([]);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => {
      setNow(Date.now());
      setReady(true);
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  const start = new Date(periodStart).getTime();
  const end = new Date(periodEnd).getTime();
  const share =
    now === null ? 0 : Math.min(1, Math.max(0, (now - start) / (end - start)));
  // While paused the ring counts down to when billing comes back, not to the old renewal.
  const until =
    status === "paused" && resumesAt !== undefined
      ? new Date(resumesAt).getTime()
      : end;
  const daysLeft =
    now === null ? null : Math.max(0, Math.ceil((until - now) / DAY));
  const date = (t: Date | string | number) =>
    hydrated
      ? new Intl.DateTimeFormat(loc, {
          month: "short",
          day: "numeric",
          year:
            new Date(t).getFullYear() !== new Date(now ?? end).getFullYear()
              ? "numeric"
              : undefined,
        }).format(new Date(t))
      : "";
  const money = (n: number) =>
    new Intl.NumberFormat(loc, {
      style: "currency",
      currency,
      minimumFractionDigits: n % 1 ? 2 : 0,
      maximumFractionDigits: 2,
    }).format(n);
  const resumeAt = addMonths(end, months);
  const busy = act.status === "pending" || act.status === "success";

  const state =
    status === "paused"
      ? `Paused until ${date(resumesAt ?? end)}`
      : status === "canceling"
        ? `Ends ${date(end)}`
        : status === "trialing"
          ? `Trial ends ${date(end)}`
          : status === "past_due"
            ? "Payment failed"
            : `Renews ${date(end)}`;

  const go = (s: 0 | 1 | 2) => {
    if (busy) return;
    setStep(s);
    setAct({ kind: null, status: "idle" });
    // Focus follows once the surface is mostly turned.
    window.setTimeout(
      () => faceRefs.current[s]?.focus({ preventScroll: true }),
      reduced ? 0 : FACES_MORPH / 2,
    );
  };

  const run = async (
    kind: "pause" | "cancel" | "resume" | "card",
    fn: (() => Promise<unknown>) | undefined,
    done: string,
  ) => {
    if (!fn || busy) return;
    setAct({ kind, status: "pending" });
    try {
      await fn();
      setAct({ kind, status: "success" });
      setSaid(done);
      window.setTimeout(
        () => {
          if (kind !== "card") setStep(0);
          setAct({ kind: null, status: "idle" });
        },
        kind === "card" ? 1200 : reduced ? 600 : 900,
      );
    } catch (e) {
      setAct({
        kind,
        status: "error",
        error: errorOf(e, "That didn’t go through. Try again."),
      });
    }
  };

  const st = (kind: "pause" | "cancel" | "resume" | "card") =>
    act.kind === kind ? act.status : "idle";
  const ghost = `inline-flex h-10 cursor-pointer items-center justify-center rounded-full px-4 text-[13.5px] font-medium ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;
  const ending = status === "paused" || status === "canceling";

  return (
    <section
      aria-labelledby={`${baseId}-plan`}
      className={`w-full max-w-[440px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 440px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the plan, and the ring of its billing period. */}
        <div
          className="rounded-[22px] p-4 text-primary-foreground"
          style={{
            ...LIT,
            filter: ending ? "saturate(0.55)" : "none",
            transition: reduced ? "none" : `filter 500ms ${EASE}`,
          }}
        >
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="text-[12.5px] text-primary-foreground/70">
                Your plan
              </p>
              <h2
                id={`${baseId}-plan`}
                className="mt-0.5 text-[20px] font-medium leading-tight tracking-[-0.02em]"
              >
                {plan.name}
                {plan.seats ? (
                  <span className="text-primary-foreground/70">
                    {" "}
                    · {plan.seats} seats
                  </span>
                ) : null}
              </h2>
              <p className="mt-2 flex items-baseline gap-1">
                <span className="text-[30px] font-medium leading-none tracking-[-0.04em] tabular-nums">
                  <NumberRoll
                    value={plan.price}
                    locales={locale}
                    format={{
                      style: "currency",
                      currency,
                      minimumFractionDigits: plan.price % 1 ? 2 : 0,
                      maximumFractionDigits: 2,
                    }}
                    duration={800}
                  />
                </span>
                <span className="text-[13px] text-primary-foreground/70">
                  /{plan.interval === "year" ? "yr" : "mo"}
                </span>
              </p>
            </div>
            <PeriodRing
              share={ending ? 1 : share}
              days={daysLeft}
              dim={ending}
              reduced={reduced}
            />
          </div>
          <p
            className={`mt-3 inline-flex h-7 items-center gap-1.5 rounded-full px-2.5 text-[12.5px] font-medium ${status === "past_due" ? "text-amber-200" : ""}`}
            style={{ background: mix("var(--primary-foreground)", 14) }}
            role="status"
          >
            <span
              aria-hidden="true"
              className={`size-1.5 rounded-full ${status === "past_due" ? "bg-amber-400" : ending ? "bg-primary-foreground/55" : "bg-emerald-300"}`}
            />
            <TextMorph>{hydrated ? state : " "}</TextMorph>
          </p>
        </div>

        {/* Flat: the details, or the way out, which always offers a pause first. */}
        <Faces active={step} reduced={reduced} ready={ready}>
          <div
            ref={(el) => {
              faceRefs.current[0] = el;
            }}
            tabIndex={-1}
            className="px-2 pb-1 pt-1 outline-none"
          >
            {usage.length > 0 && (
              <div className="space-y-2.5 px-1 pt-3">
                {usage.map((u) => {
                  const pct = Math.min(1, u.used / u.limit);
                  const hot = pct >= 0.9;
                  return (
                    <div key={u.id}>
                      <div className="flex items-baseline justify-between gap-3 text-[13px]">
                        <span className="text-foreground">{u.label}</span>
                        <span className="tabular-nums text-muted-foreground">
                          <NumberRoll
                            value={u.used}
                            locales={locale}
                            className={
                              hot
                                ? "font-medium text-amber-600 dark:text-amber-400"
                                : "text-foreground"
                            }
                          />{" "}
                          / {new Intl.NumberFormat(loc).format(u.limit)}
                          {u.unit ? ` ${u.unit}` : ""}
                        </span>
                      </div>
                      <div
                        className="mt-1.5 h-1 overflow-hidden rounded-full bg-muted"
                        role="meter"
                        aria-label={u.label}
                        aria-valuemin={0}
                        aria-valuemax={u.limit}
                        aria-valuenow={u.used}
                      >
                        <span
                          className={`block h-full origin-left rounded-full ${hot ? "bg-amber-500" : "bg-primary"}`}
                          style={{
                            transform: `scaleX(${ready ? pct : 0})`,
                            transition: reduced
                              ? "none"
                              : `transform 900ms ${EASE}`,
                          }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {card && (
              <div className="mt-3 flex h-12 items-center gap-3 border-t border-border px-1 pt-3">
                <span
                  aria-hidden="true"
                  className="flex h-7 w-10 shrink-0 items-center justify-center rounded-[6px] border border-border bg-background font-mono text-[9px] font-medium uppercase tracking-[0.06em] text-foreground"
                >
                  {card.brand.slice(0, 4)}
                </span>
                <span className="min-w-0 flex-1 text-[13px]">
                  <span className="block truncate text-foreground">
                    {card.brand} •••• {card.last4}
                  </span>
                  <span className="block text-[12px] text-muted-foreground">
                    Expires {String(card.expMonth).padStart(2, "0")}/
                    {String(card.expYear).slice(-2)}
                  </span>
                </span>
                {onUpdateCard && (
                  <StatusButton
                    variant="ghost"
                    size="sm"
                    status={st("card")}
                    labels={{
                      idle: "Update",
                      pending: "Opening",
                      success: "Opened",
                      error: "Try again",
                    }}
                    onClick={() =>
                      void run("card", onUpdateCard, "Opened the payment page.")
                    }
                    className="-mr-1 shrink-0 text-foreground"
                  />
                )}
              </div>
            )}
            {act.kind === "card" && act.error && (
              <p
                role="alert"
                className="px-1 pt-1 text-[12px] text-red-600 dark:text-red-400"
              >
                {act.error}
              </p>
            )}

            {invoices.length > 0 && (
              <div className="mt-3 border-t border-border px-1 pt-2.5">
                <p className="text-[12px] text-muted-foreground">Invoices</p>
                <ul className="mt-1">
                  {invoices.slice(0, 3).map((inv) => (
                    <li
                      key={inv.id}
                      className="flex h-9 items-center gap-3 text-[13px]"
                    >
                      <span className="min-w-0 flex-1 text-foreground">
                        {date(inv.date)}
                      </span>
                      <span
                        className={`rounded-full px-2 py-0.5 text-[11px] font-medium ${inv.status === "paid" ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" : inv.status === "open" ? "bg-amber-500/10 text-amber-700 dark:text-amber-400" : "bg-red-500/10 text-red-600 dark:text-red-400"}`}
                      >
                        {inv.status === "paid"
                          ? "Paid"
                          : inv.status === "open"
                            ? "Open"
                            : "Failed"}
                      </span>
                      <span className="w-[72px] text-right tabular-nums text-foreground">
                        {money(inv.amount)}
                      </span>
                      {inv.url ? (
                        <a
                          href={inv.url}
                          target="_blank"
                          rel="noreferrer"
                          aria-label={`Download the invoice of ${date(inv.date)}`}
                          className={`-mr-1 flex size-7 items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_FOCUS}`}
                        >
                          <ArrowDownToLine
                            aria-hidden="true"
                            className="size-3.5"
                          />
                        </a>
                      ) : (
                        <span className="w-6" />
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className="mt-2.5 flex gap-2 border-t border-border pt-3">
              {ending && onResume ? (
                <StatusButton
                  status={st("resume")}
                  labels={{
                    idle: status === "paused" ? "Resume now" : "Keep my plan",
                    pending: "Resuming",
                    success: "Resumed",
                    error: "Try again",
                  }}
                  onClick={() =>
                    void run("resume", onResume, "Your plan is back on.")
                  }
                  className="h-10 flex-1 text-[13.5px]"
                  style={st("resume") === "error" ? undefined : ACTION}
                />
              ) : (
                onChangePlan && (
                  <button
                    type="button"
                    onClick={onChangePlan}
                    className={`${ghost} flex-1 text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent`}
                  >
                    Change plan
                  </button>
                )
              )}
              {!ending && (onPause || onCancel) && (
                <button
                  type="button"
                  onClick={() => go(onPause ? 1 : 2)}
                  className={`${ghost} text-muted-foreground hover:bg-accent hover:text-foreground`}
                >
                  Cancel plan
                </button>
              )}
            </div>
            {act.kind === "resume" && act.error && (
              <p
                role="alert"
                className="px-1 pt-1.5 text-[12px] text-red-600 dark:text-red-400"
              >
                {act.error}
              </p>
            )}
          </div>

          {/* Before you go: a pause, with the date it all comes back. */}
          <div
            ref={(el) => {
              faceRefs.current[1] = el;
            }}
            tabIndex={-1}
            role="group"
            aria-labelledby={`${baseId}-pause`}
            className="px-3 pb-1.5 pt-3.5 outline-none"
          >
            <h3
              id={`${baseId}-pause`}
              className="text-[16px] font-medium tracking-[-0.01em]"
            >
              Pause instead?
            </h3>
            <p className="mt-1 text-[13px] leading-relaxed text-muted-foreground">
              Keep everything as it is and pick up where you left off. You won’t
              be charged while it’s paused.
            </p>
            <SegmentedControl
              label="Pause for"
              block
              className="mt-3"
              value={String(months)}
              onValueChange={(v) => setMonths(Number(v))}
              options={pauseMonths.map((m) => ({
                value: String(m),
                label: m === 1 ? "1 month" : `${m} months`,
              }))}
            />
            <p className="mt-2.5 text-[13px] text-muted-foreground">
              Billing resumes on{" "}
              <TextMorph className="font-medium text-foreground">
                {hydrated ? date(resumeAt) : " "}
              </TextMorph>
            </p>
            <StatusButton
              status={st("pause")}
              labels={{
                idle:
                  months === 1
                    ? "Pause for 1 month"
                    : `Pause for ${months} months`,
                pending: "Pausing",
                success: "Paused",
                error: "Try again",
              }}
              onClick={() =>
                void run(
                  "pause",
                  onPause && (() => onPause(months)),
                  `Paused for ${months} months.`,
                )
              }
              className="mt-3.5 h-11 w-full text-[14.5px]"
              style={st("pause") === "error" ? undefined : ACTION}
            />
            {act.kind === "pause" && act.error && (
              <p
                role="alert"
                className="mt-1.5 text-center text-[12px] text-red-600 dark:text-red-400"
              >
                {act.error}
              </p>
            )}
            <div className="mt-1.5 flex justify-between">
              <button
                type="button"
                onClick={() => go(0)}
                disabled={busy}
                className={`${ghost} -ml-2 h-9 px-3 text-muted-foreground hover:bg-accent hover:text-foreground`}
              >
                Keep my plan
              </button>
              {onCancel && (
                <button
                  type="button"
                  onClick={() => go(2)}
                  disabled={busy}
                  className={`${ghost} -mr-2 h-9 px-3 text-muted-foreground hover:bg-accent hover:text-foreground`}
                >
                  No, cancel it
                </button>
              )}
            </div>
          </div>

          {/* Cancel: a reason, then the end date. */}
          <div
            ref={(el) => {
              faceRefs.current[2] = el;
            }}
            tabIndex={-1}
            role="group"
            aria-labelledby={`${baseId}-cancel`}
            className="px-3 pb-1.5 pt-3 outline-none"
          >
            <div className="-ml-1.5 flex items-center gap-1">
              <button
                type="button"
                aria-label="Back"
                disabled={busy}
                onClick={() => go(onPause ? 1 : 0)}
                className={`flex size-8 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
              >
                <ChevronLeft aria-hidden="true" className="size-[18px]" />
              </button>
              <h3
                id={`${baseId}-cancel`}
                className="text-[16px] font-medium tracking-[-0.01em]"
              >
                Why are you leaving?
              </h3>
            </div>
            <div
              role="radiogroup"
              aria-labelledby={`${baseId}-cancel`}
              className="mt-2.5 flex flex-wrap gap-1.5"
            >
              {reasons.map((r) => {
                const on = r === reason;
                return (
                  <button
                    key={r}
                    type="button"
                    role="radio"
                    aria-checked={on}
                    disabled={busy}
                    onClick={() => setReason(r)}
                    className={`h-8 cursor-pointer rounded-full px-3 text-[12.5px] ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${on ? "bg-primary/[0.08] font-medium text-primary shadow-[inset_0_0_0_1.5px_var(--primary)]" : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"}`}
                    style={{
                      transition: reduced
                        ? "none"
                        : `box-shadow 260ms ${EASE_THROW}, background-color 200ms`,
                    }}
                  >
                    {r}
                  </button>
                );
              })}
            </div>
            <Textarea
              aria-label="Anything we could have done better?"
              placeholder="Anything we could have done better? (optional)"
              value={comment}
              onValueChange={setComment}
              disabled={busy}
              minRows={2}
              maxRows={4}
              maxLength={500}
              showCount={false}
              className="mt-2.5"
            />
            <StatusButton
              variant="outline"
              status={st("cancel")}
              labels={{
                idle: "Cancel subscription",
                pending: "Cancelling",
                success: "Cancelled",
                error: "Try again",
              }}
              disabled={!reason && st("cancel") === "idle"}
              onClick={() =>
                void run(
                  "cancel",
                  onCancel && (() => onCancel(reason ?? "", comment.trim())),
                  `Cancelled. ${plan.name} stays on until ${date(end)}.`,
                )
              }
              className="mt-2.5 h-11 w-full text-[14.5px] text-red-600 disabled:opacity-45 dark:text-red-400"
            />
            <p
              role={act.kind === "cancel" && act.error ? "alert" : undefined}
              className={`mt-1.5 text-center text-[12px] ${act.kind === "cancel" && act.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
            >
              {act.kind === "cancel" && act.error
                ? act.error
                : hydrated
                  ? `You keep ${plan.name} until ${date(end)}.`
                  : " "}
            </p>
          </div>
        </Faces>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default Subscription;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * FACES: the states of one surface, in the same place
 *
 * The active face is in flow; the others are laid over it, faded
 * and nudged aside (faces before it to the left, faces after it to
 * the right), so switching reads as the surface turning to its
 * next side. The height eases between the faces' measured heights,
 * so nothing around it jumps. Used by the blocks (the wallet's
 * activity and keypad, a pricing card and its checkout, a booking's
 * times, details and confirmation).
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16,1,0.3,1)";
export const FACES_MORPH = 460;

export function Faces({
  active,
  reduced,
  ready,
  className = "",
  children,
}: {
  active: number;
  reduced: boolean;
  /** False until the first paint, so the faces don't animate into place on mount. */
  ready: boolean;
  className?: string;
  children: React.ReactNode[];
}) {
  const refs = React.useRef<(HTMLDivElement | null)[]>([]);
  const [heights, setHeights] = React.useState<number[] | null>(null);
  const count = children.length;

  React.useLayoutEffect(() => {
    const els = refs.current.slice(0, count);
    const observer = new ResizeObserver(() => {
      const next = els.map((el) => el?.offsetHeight ?? 0);
      setHeights((p) =>
        p && p.length === next.length && p.every((h, i) => h === next[i])
          ? p
          : next,
      );
    });
    els.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [count]);

  const face = (i: number): React.CSSProperties => {
    const on = i === active;
    return {
      opacity: on ? 1 : 0,
      transform:
        on || reduced ? "none" : `translateX(${i < active ? -18 : 18}px)`,
      filter: on || reduced ? "none" : "blur(4px)",
      transition: !ready
        ? "none"
        : reduced
          ? "opacity 160ms ease-out"
          : on
            ? `opacity 320ms ${EASE} 90ms, transform ${FACES_MORPH}ms ${EASE}, filter 320ms ${EASE} 90ms`
            : `opacity 140ms ease-out, transform ${FACES_MORPH}ms ${EASE}, filter 200ms ease-out`,
    };
  };

  return (
    <div
      className={`relative overflow-clip ${className}`}
      style={{
        height: heights ? heights[active] : undefined,
        transition:
          ready && !reduced ? `height ${FACES_MORPH}ms ${EASE}` : "none",
      }}
    >
      {children.map((child, i) => (
        <div
          key={i}
          ref={(el) => {
            refs.current[i] = el;
          }}
          inert={active !== i || undefined}
          aria-hidden={active !== i || undefined}
          className={
            active === i
              ? "relative"
              : "pointer-events-none absolute inset-x-0 top-0"
          }
          style={face(i)}
        >
          {child}
        </div>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SEGMENTED CONTROL: one of a few, side by side
 *
 *   pick     the thumb is thrown to the new segment with a slight
 *            overshoot while its width eases to the new label
 *   press    the thumb gives a little under the finger
 *   keys     a radiogroup: arrows move and select, Home/End jump;
 *            one tab stop for the whole control
 * ───────────────────────────────────────────────────────── */

export interface SegmentOption {
  value: string;
  label: React.ReactNode;
  icon?: React.ReactNode;
  /** Required when `label` isn't text (icon-only segments). */
  ariaLabel?: string;
  disabled?: boolean;
}

export interface SegmentedControlProps {
  options: SegmentOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Accessible name of the group. */
  label: string;
  /** 28px, 34px, or 40px tall (matches tactile sliders). */
  size?: "sm" | "md" | "lg";
  /** Stretch to the parent's width with equal segments. */
  block?: boolean;
  className?: string;
  /** Corner radius: "full" (pill, default) or "rounded" (concentric rounded container). */
  radius?: "full" | "rounded";
}

type Mark = { x: number; w: number };

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  size = "md",
  block,
  className = "",
  radius = "full",
}: SegmentedControlProps) {
  const reduced = useInteractionReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(defaultValue ?? options[0]?.value);
  const current = value !== undefined ? value : own;
  const [mark, setMark] = React.useState<Mark | null>(null);
  const [ready, setReady] = React.useState(false);
  const [pressing, setPressing] = React.useState(false);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const measure = () => {
      const el = current
        ? root.querySelector<HTMLElement>(
            `[data-segment="${CSS.escape(current)}"]`,
          )
        : null;
      if (!el) return setMark(null);
      const next = { x: el.offsetLeft, w: el.offsetWidth };
      setMark((p) => (p && p.x === next.x && p.w === next.w ? p : next));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    root.querySelectorAll("[data-segment]").forEach((el) => ro.observe(el));
    return () => ro.disconnect();
  }, [current, options]);

  React.useEffect(() => {
    if (!mark || ready) return;
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, ready]);

  const pick = (v: string) => {
    if (value === undefined) setOwn(v);
    onValueChange?.(v);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const enabled = options.filter((o) => !o.disabled);
    const index = enabled.findIndex((o) => o.value === current);
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown")
      next = (index + 1) % enabled.length;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp")
      next = (index - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next < 0) return;
    e.preventDefault();
    const v = enabled[next].value;
    pick(v);
    rootRef.current
      ?.querySelector<HTMLElement>(`[data-segment="${CSS.escape(v)}"]`)
      ?.focus();
  };

  const isLg = size === "lg";
  const isSm = size === "sm";
  const isPill = radius === "full";

  // Concentric corner radius matching compact slider geometry
  const rootRadius = isPill
    ? "rounded-full"
    : isLg
      ? "rounded-[13px]"
      : isSm
        ? "rounded-[9px]"
        : "rounded-[11px]";
  const itemRadius = isPill
    ? "rounded-full"
    : isLg
      ? "rounded-[9px]"
      : isSm
        ? "rounded-[7px]"
        : "rounded-[9px]";

  // Proportional sizing: "md" is compact 34px, "lg" is 40px, "sm" is 28px
  const rootPadding = isLg ? "p-1" : "p-0.5";
  const rootHeight = isLg ? "h-10" : isSm ? "h-7" : "h-8.5";
  const indicatorInset = isLg ? "top-1 bottom-1" : "top-0.5 bottom-0.5";
  const itemHeightClass = isLg
    ? "h-8 px-3 text-[13px]"
    : isSm
      ? "h-6 px-2 text-[11.5px]"
      : "h-[30px] px-2.5 text-[12px]";

  return (
    <div
      ref={rootRef}
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`relative isolate select-none items-center ${rootHeight} ${rootRadius} ${rootPadding} border border-black/[0.04] dark:border-white/[0.06] bg-[#f4f4f6] dark:bg-zinc-900/50 ${
        block ? "flex w-full" : "inline-flex"
      } ${className}`}
    >
      <span
        aria-hidden="true"
        className={`pointer-events-none absolute left-0 ${indicatorInset} ${itemRadius} bg-white dark:bg-zinc-800 border border-black/[0.05] dark:border-white/[0.1] shadow-[0_1px_2px_rgba(0,0,0,0.04)]`}
        style={{
          transform: `translate3d(${mark?.x ?? 0}px, 0, 0) scale(${pressing && !reduced ? 0.97 : 1})`,
          width: mark?.w ?? 0,
          opacity: mark ? 1 : 0,
          transition:
            reduced || !ready
              ? "none"
              : `transform 440ms ${EASE_THROW}, width 400ms ${EASE_OUT}, opacity 200ms ${EASE_OUT}`,
        }}
      />
      {options.map((option) => {
        const on = option.value === current;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={on}
            aria-label={option.ariaLabel}
            data-segment={option.value}
            disabled={option.disabled}
            tabIndex={on ? 0 : -1}
            onClick={() => pick(option.value)}
            onPointerDown={() => on && setPressing(true)}
            onPointerUp={() => setPressing(false)}
            onPointerLeave={() => setPressing(false)}
            className={`relative z-10 inline-flex items-center justify-center gap-1.5 whitespace-nowrap ${itemRadius} font-medium cursor-pointer transition-colors duration-200 disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${itemHeightClass} ${
              block ? "flex-1" : ""
            } ${on ? "text-zinc-950 font-semibold dark:text-white" : "text-zinc-600 hover:text-zinc-950 dark:text-zinc-400 dark:hover:text-zinc-100"} ${INTERACTION_FOCUS}`}
          >
            {option.icon}
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

export default SegmentedControl;

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { Field, fieldSurface, useFieldIds, useShake } from "./imported-field";
import { NumberRoll } from "./number-roll";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TEXTAREA: grows with what you write
 *
 *   grow     a hidden copy of the text is measured and the box
 *            eases to its height, between minRows and maxRows,
 *            then scrolls; it never snaps a line taller
 *   scroll   past maxRows the browser's scrollbar never shows:
 *            lines fade out at the top and bottom edges instead of
 *            being sliced, and a 3px thumb inside the padding
 *            shows where you are while you scroll, then fades;
 *            it can be dragged
 *   compose  `footer` (tools) and `action` (send) sit inside the box;
 *            `onSubmit` sends on ⌘↵ / Ctrl+Enter, with the hint rising
 *            in beside the action once there's something to send
 *   count    with maxLength, the count rolls as you type and turns
 *            amber in the last tenth, red at the limit
 *   error    same as every field: red line, hint gives way, shake
 *
 * Text is 16px on phones so iOS never zooms the page on focus.
 * ───────────────────────────────────────────────────────── */

export interface TextareaProps extends Omit<
  React.TextareaHTMLAttributes<HTMLTextAreaElement>,
  "onSubmit"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  minRows?: number;
  maxRows?: number;
  /** Show "12 / 280" beside the label when maxLength is set. */
  showCount?: boolean;
  /** Tools inside the box, under the text on the left (attach, emoji). */
  footer?: React.ReactNode;
  /** The main action inside the box on the right (send). */
  action?: React.ReactNode;
  /** ⌘↵ / Ctrl+Enter calls this with the text. */
  onSubmit?: (value: string) => void;
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLTextAreaElement>;
  className?: string;
  textareaClassName?: string;
}

const TYPE =
  "px-4 py-[9px] text-[16px] leading-[1.5] sm:text-[13.5px] sm:leading-[1.55]";
const FADE = 14;

const subscribeNoop = () => () => {};
const isMac = () => /Mac|iPhone|iPad/.test(navigator.platform);

export function Textarea({
  label,
  hint,
  error,
  minRows = 3,
  maxRows = 10,
  showCount = true,
  footer,
  action,
  onSubmit,
  onValueChange,
  ref,
  id,
  className = "",
  textareaClassName = "",
  value,
  defaultValue,
  onChange,
  onKeyDown,
  onFocus,
  onBlur,
  maxLength,
  disabled,
  required,
  ...props
}: TextareaProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const mac = React.useSyncExternalStore(subscribeNoop, isMac, () => true);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const mirror = React.useRef<HTMLDivElement>(null);
  const area = React.useRef<HTMLTextAreaElement>(null);
  const thumb = React.useRef<HTMLSpanElement>(null);
  const [height, setHeight] = React.useState<number | null>(null);
  const [overflows, setOverflows] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const fadeTimer = React.useRef(0);
  const drag = React.useRef<{ y: number; top: number } | null>(null);
  const shakeRef = useShake<HTMLDivElement>(!!error);

  // Height from the mirror, in whole lines between minRows and maxRows (line metrics read from CSS, so
  // the 16px phone type and the 13.5px desktop type both measure right).
  React.useLayoutEffect(() => {
    const el = mirror.current;
    if (!el) return;
    const measure = () => {
      const style = getComputedStyle(el);
      const line = parseFloat(style.lineHeight) || 21;
      const pad =
        parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
      const next = Math.round(
        Math.min(
          maxRows * line + pad,
          Math.max(minRows * line + pad, el.offsetHeight),
        ),
      );
      setHeight((h) => (h === next ? h : next));
      setOverflows((o) =>
        o === el.offsetHeight > maxRows * line + pad + 1 ? o : !o,
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [current, minRows, maxRows]);

  // Edge fades and thumb, written straight to the elements: no render per scroll frame.
  const paint = React.useCallback((show: boolean) => {
    const el = area.current;
    const t = thumb.current;
    if (!el) return;
    const max = el.scrollHeight - el.clientHeight;
    const top = max > 1 ? Math.min(FADE, el.scrollTop) : 0;
    const bottom = max > 1 ? Math.min(FADE, max - el.scrollTop) : 0;
    const mask = `linear-gradient(to bottom, transparent 0, #000 ${top}px, #000 calc(100% - ${bottom}px), transparent 100%)`;
    el.style.maskImage = mask;
    el.style.webkitMaskImage = mask;
    if (!t) return;
    if (max <= 1) {
      t.style.opacity = "0";
      return;
    }
    const track = el.clientHeight - 12;
    const size = Math.max(24, (el.clientHeight / el.scrollHeight) * track);
    t.style.height = `${size}px`;
    t.style.transform = `translateY(${6 + (el.scrollTop / max) * (track - size)}px)`;
    if (show) {
      t.style.opacity = "1";
      window.clearTimeout(fadeTimer.current);
      fadeTimer.current = window.setTimeout(() => {
        if (!drag.current && thumb.current) thumb.current.style.opacity = "0";
      }, 900);
    }
  }, []);

  React.useEffect(() => () => window.clearTimeout(fadeTimer.current), []);
  React.useLayoutEffect(() => paint(false), [paint, height, current]);

  const setRefs = (el: HTMLTextAreaElement | null) => {
    area.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLTextAreaElement | null>).current = el;
  };

  const count = current.length;
  const near = maxLength ? count >= maxLength * 0.9 : false;
  const full = maxLength ? count >= maxLength : false;
  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;
  const canSend = !!onSubmit && focused && current.trim().length > 0;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
      aside={
        maxLength && showCount ? (
          <span
            className={
              full
                ? "text-red-600 dark:text-red-400"
                : near
                  ? "text-amber-600 dark:text-amber-400"
                  : ""
            }
            style={{ transition: "color 200ms" }}
          >
            <NumberRoll value={count} /> / {maxLength}
          </span>
        ) : undefined
      }
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled, round: false })} flex-col items-stretch`}
      >
        <div className="relative">
          {/* The measuring copy: same type and padding, never seen. */}
          <div
            ref={mirror}
            aria-hidden="true"
            className={`pointer-events-none invisible absolute inset-x-0 top-0 whitespace-pre-wrap break-words ${TYPE} ${textareaClassName}`}
          >
            {current + "​"}
          </div>
          <textarea
            ref={setRefs}
            id={ids.id}
            value={value}
            defaultValue={defaultValue}
            maxLength={maxLength}
            disabled={disabled}
            required={required}
            aria-invalid={error ? true : undefined}
            aria-describedby={describedBy}
            aria-keyshortcuts={
              onSubmit ? "Meta+Enter Control+Enter" : undefined
            }
            onChange={(e) => {
              if (value === undefined) setText(e.target.value);
              onChange?.(e);
              onValueChange?.(e.target.value);
            }}
            onKeyDown={(e) => {
              onKeyDown?.(e);
              if (
                onSubmit &&
                e.key === "Enter" &&
                (e.metaKey || e.ctrlKey) &&
                current.trim()
              ) {
                e.preventDefault();
                onSubmit(current);
              }
            }}
            onFocus={(e) => {
              setFocused(true);
              onFocus?.(e);
            }}
            onBlur={(e) => {
              setFocused(false);
              onBlur?.(e);
            }}
            onScroll={() => paint(true)}
            style={{
              height: height ?? undefined,
              transition: reduced ? "none" : `height 260ms ${EASE_OUT}`,
            }}
            className={`block w-full resize-none bg-transparent outline-none placeholder:text-muted-foreground/70 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden ${overflows ? "pr-6" : ""} ${TYPE} ${textareaClassName}`}
            {...props}
          />
          {/* Our scroll thumb: 3px, inside the padding, shown while scrolling; a wider strip takes the drag. */}
          {overflows && (
            <span
              aria-hidden="true"
              className="absolute right-0 top-0 h-full w-4 touch-none"
              onPointerDown={(e) => {
                const el = area.current;
                if (!el) return;
                e.preventDefault();
                e.currentTarget.setPointerCapture(e.pointerId);
                drag.current = { y: e.clientY, top: el.scrollTop };
                paint(true);
              }}
              onPointerMove={(e) => {
                const el = area.current;
                const d = drag.current;
                if (!el || !d) return;
                const size = parseFloat(thumb.current?.style.height ?? "24");
                const track = el.clientHeight - 12 - size;
                el.scrollTop =
                  d.top +
                  ((e.clientY - d.y) / Math.max(1, track)) *
                    (el.scrollHeight - el.clientHeight);
              }}
              onPointerUp={() => {
                drag.current = null;
                paint(true);
              }}
              onPointerCancel={() => {
                drag.current = null;
              }}
            >
              <span
                ref={thumb}
                className="absolute right-1.5 top-0 w-[3px] rounded-full bg-foreground/25 transition-[opacity,width] duration-300 hover:w-[5px] hover:bg-foreground/35"
                style={{ opacity: 0 }}
              />
            </span>
          )}
        </div>
        {(footer || action || onSubmit) && (
          <div className="flex min-h-10 items-center gap-2 px-2 pb-2">
            <div className="flex min-w-0 flex-1 items-center gap-1">
              {footer}
            </div>
            {onSubmit && (
              <span
                aria-hidden="true"
                className="hidden shrink-0 font-mono text-[11px] text-muted-foreground sm:inline"
                style={{
                  opacity: canSend ? 1 : 0,
                  filter: canSend || reduced ? "none" : "blur(3px)",
                  transition: reduced
                    ? "none"
                    : `opacity 200ms ${EASE_OUT}, filter 200ms ${EASE_OUT}`,
                }}
              >
                {mac ? "⌘↵" : "Ctrl ↵"} to send
              </span>
            )}
            {action}
          </div>
        )}
      </div>
    </Field>
  );
}

export default Textarea;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
              : show
                ? `opacity 280ms ${EASE_OUT} 60ms, filter 280ms ${EASE_OUT} 60ms, transform 380ms ${EASE_OUT}`
                : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 200ms ${EASE_OUT}`,
          }}
        >
          {show ? children : kept}
        </p>
      </div>
    </div>
  );
}

export function Field({
  id,
  label,
  aside,
  hint,
  error,
  required,
  className = "",
  children,
}: FieldProps) {
  const reduced = useInteractionReducedMotion();
  const ids = { hint: `${id}-hint`, error: `${id}-error` };
  return (
    <div className={`flex w-full flex-col ${className}`}>
      {(label || aside) && (
        <div className="flex items-baseline justify-between gap-3 px-3 pb-1.5">
          {label && (
            <label
              htmlFor={id}
              className="text-[13px] font-medium text-foreground"
            >
              {label}
              {required && (
                <span
                  aria-hidden="true"
                  className="ml-0.5 text-muted-foreground"
                >
                  *
                </span>
              )}
            </label>
          )}
          {aside && (
            <span className="text-[12px] tabular-nums text-muted-foreground">
              {aside}
            </span>
          )}
        </div>
      )}
      {children}
      <Line
        show={!error && !!hint}
        id={ids.hint}
        tone="text-muted-foreground"
        reduced={reduced}
      >
        {hint}
      </Line>
      <Line
        show={!!error}
        id={ids.error}
        tone="text-red-600 dark:text-red-400"
        reduced={reduced}
      >
        {error}
      </Line>
    </div>
  );
}

export default Field;

